export function Backlog({
  title = "{{title}}",
  count = {{count}},
  sortBy = "{{sortBy}}",
  accent = "{{accent}}",
  showNumbers = {{showNumbers}},
}) {
  const items = [
    { priority: "High priority", color: "#b0362a", label: "Redesign onboarding checklist" },
    { priority: "Medium priority", color: "#8a5d00", label: "Add CSV export to reports" },
    { priority: "Medium priority", color: "#8a5d00", label: "Investigate slow search index" },
    { priority: "Low priority", color: "#1a7a4c", label: "Refresh empty-state illustrations" },
  ];
  return (
    <section aria-labelledby="backlog-heading" style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430",
      background: "#FAF7F2", padding: 16, borderRadius: 12, maxWidth: 360, boxSizing: "border-box" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
        <h3 id="backlog-heading" style={{ margin: 0, fontSize: 16 }}>{title}</h3>
        <span style={{ fontSize: 12, fontWeight: 600, background: accent, color: "#241430", padding: "3px 8px", borderRadius: 999, whiteSpace: "nowrap" }}>{count} items pending</span>
      </div>
      <p style={{ margin: "6px 0 10px", fontSize: 12, color: "#241430b3" }}>Sorted by <strong>{sortBy}</strong></p>
      <ol style={{ margin: 0, paddingLeft: 22, listStyle: showNumbers ? "decimal" : "disc" }}>
        {items.map((item, i) => (
          <li key={item.label} style={{ marginTop: i === 0 ? 0 : 8 }}>
            <span style={{ display: "block", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.03em", color: item.color }}>{item.priority}</span>
            <span style={{ display: "block", fontSize: 14 }}>{item.label}</span>
          </li>
        ))}
      </ol>
    </section>
  );
}
